from typing import List

def separate_paren_groups(paren_string: str) -> List[str]:
    result = []
    current = []
    balance = 0

    for char in paren_string:
        if char == ' ':
            continue
        if char == '(':
            balance += 1
            current.append(char)
        elif char == ')':
            balance -= 1
            current.append(char)
            if balance == 0:
                result.append(''.join(current))
                current = []

    return result
