from typing import List

def parse_nested_parens(paren_string: str) -> List[int]:
    result = []
    current_max = 0
    current_depth = 0

    for group in paren_string.split():
        current_max = 0
        current_depth = 0
        for char in group:
            if char == '(':
                current_depth += 1
                if current_depth > current_max:
                    current_max = current_depth
            elif char == ')':
                current_depth -= 1
        result.append(current_max)

    return result
