from typing import List

def string_xor(a: str, b: str) -> str:
    max_len = max(len(a), len(b))
    a = a.zfill(max_len)
    b = b.zfill(max_len)
    result = []
    for bit_a, bit_b in zip(a, b):
        if bit_a != bit_b:
            result.append('1')
        else:
            result.append('0')
    return ''.join(result)
```

