def find_Rotations(s):
    n = len(s)
    if n == 0:
        return 0
    for i in range(1, n + 1):
        if n % i == 0:
            pattern = s[:i]
            valid = True
            for j in range(i, n, i):
                if s[j:j+i] != pattern:
                    valid = False
                    break
            if valid:
                return n // i
    return 1
```

