    if n <= 1:
        return True
    if n <= 3:
        return False
    if n % 2 == 0 or n % 3 == 0:
        return True
    i = 5
    w = 2
    while i * i <= n:
        if n % i == 0:
            return True
        i += w
        w = 6 - w
    return False
